import { DurableObject } from "cloudflare:workers";

// =====================================================================
// ASSETS (base64-kodiert, damit keine Escaping-Probleme beim Einbetten
// entstehen -- b64d() dekodiert sie zur Laufzeit als UTF-8-Strings)
// =====================================================================
function b64d(b64) {
  const bin = atob(b64);
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return new TextDecoder("utf-8").decode(bytes);
}

const APP_CSS_B64 = "";
const APP_JS_B64 = "";
const APP_HTML_B64 = "";
const LOGIN_HTML_B64 = "";
const LOGIN_JS_B64 = "";
const ADMIN_HTML_B64 = "";
const ADMIN_JS_B64 = "";

const APP_CSS = b64d(APP_CSS_B64);
const APP_JS = b64d(APP_JS_B64);
const APP_HTML_RAW = b64d(APP_HTML_B64);
const LOGIN_HTML = b64d(LOGIN_HTML_B64);
const LOGIN_JS = b64d(LOGIN_JS_B64);
const ADMIN_HTML = b64d(ADMIN_HTML_B64);
const ADMIN_JS = b64d(ADMIN_JS_B64);

function buildAppHtml(displayName, isAdmin) {
  const userInfoScript =
    '<script>window.CURRENT_USER=' + JSON.stringify(displayName) + ';window.IS_ADMIN=' + (isAdmin ? "true" : "false") + ';</script>';
  const adminLink = isAdmin ? '<a href="/admin" class="admin-link">Admin</a>' : "";
  return APP_HTML_RAW
    .replace('<link rel="stylesheet" href="style.css" />', "<style>" + APP_CSS + "</style>")
    .replace("<!--ADMIN_LINK-->", adminLink)
    .replace("<!--USERINFO-->", userInfoScript)
    .replace('<script src="app.js"></script>', "<script>" + APP_JS + "</script>");
}

function htmlResponse(html) {
  return new Response(html, { headers: { "Content-Type": "text/html; charset=utf-8" } });
}
function jsResponse(js) {
  return new Response(js, { headers: { "Content-Type": "application/javascript; charset=utf-8" } });
}
function json(data, status) {
  return new Response(JSON.stringify(data), {
    status: status || 200,
    headers: { "Content-Type": "application/json; charset=utf-8" },
  });
}

// =====================================================================
// AUTH-MODUL -- bewusst separat gehalten (eigene Tabellen in D1, eigene
// Routen unter /auth/* und /admin/*), damit es später auch für andere
// Projekte wiederverwendet werden kann.
// =====================================================================

function bytesToHex(bytes) {
  return [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");
}
function hexToBytes(hex) {
  const arr = new Uint8Array(hex.length / 2);
  for (let i = 0; i < arr.length; i++) arr[i] = parseInt(hex.substr(i * 2, 2), 16);
  return arr;
}

async function hashPassword(password, existingSaltHex) {
  const enc = new TextEncoder();
  const salt = existingSaltHex ? hexToBytes(existingSaltHex) : crypto.getRandomValues(new Uint8Array(16));
  const keyMaterial = await crypto.subtle.importKey("raw", enc.encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", salt, iterations: 100000, hash: "SHA-256" },
    keyMaterial,
    256
  );
  return { hash: bytesToHex(new Uint8Array(bits)), salt: bytesToHex(salt) };
}

function timingSafeEqual(a, b) {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}

function randomToken() {
  return bytesToHex(crypto.getRandomValues(new Uint8Array(32)));
}

function parseCookies(request) {
  const header = request.headers.get("Cookie") || "";
  const out = {};
  header.split(";").forEach((p) => {
    const idx = p.indexOf("=");
    if (idx === -1) return;
    const k = p.slice(0, idx).trim();
    const v = p.slice(idx + 1).trim();
    if (k) out[k] = decodeURIComponent(v);
  });
  return out;
}

function sessionCookie(token) {
  const maxAge = 60 * 60 * 24 * 7; // 7 Tage
  return `session=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`;
}
function clearSessionCookie() {
  return "session=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0";
}

async function getSessionUser(request, env) {
  const cookies = parseCookies(request);
  const token = cookies["session"];
  if (!token) return null;
  const row = await env.DB.prepare(
    "SELECT u.* FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token = ?1 AND s.expires_at > datetime('now')"
  )
    .bind(token)
    .first();
  return row || null;
}

async function handleRegister(request, env) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungültige Anfrage." }, 400);
  }
  const vorname = (body.vorname || "").trim();
  const nachname = (body.nachname || "").trim();
  const username = (body.username || "").trim();
  const password = body.password || "";
  const email = (body.email || "").trim() || null;
  const handynummer = (body.handynummer || "").trim() || null;

  if (!vorname || !nachname || !username || !password || !email) {
    return json({ error: "Vorname, Nachname, Benutzername, Passwort und E-Mail sind Pflichtfelder." }, 400);
  }
  if (password.length < 6) {
    return json({ error: "Das Passwort muss mindestens 6 Zeichen lang sein." }, 400);
  }

  const existing = await env.DB.prepare("SELECT id FROM users WHERE username = ?1").bind(username).first();
  if (existing) {
    return json({ error: "Dieser Benutzername ist bereits vergeben." }, 409);
  }

  const { hash, salt } = await hashPassword(password);

  await env.DB.prepare(
    `INSERT INTO users (username, vorname, nachname, email, handynummer, password_hash, password_salt, role, status)
     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 'user', 'pending')`
  )
    .bind(username, vorname, nachname, email, handynummer, hash, salt)
    .run();

  await notifyAdmins(env);
  return json({ ok: true });
}

async function handleLogin(request, env) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungültige Anfrage." }, 400);
  }
  const username = (body.username || "").trim();
  const password = body.password || "";

  const user = await env.DB.prepare("SELECT * FROM users WHERE username = ?1").bind(username).first();
  if (!user) {
    return json({ error: "Benutzername oder Passwort ist falsch." }, 401);
  }

  const { hash } = await hashPassword(password, user.password_salt);
  if (!timingSafeEqual(hash, user.password_hash)) {
    return json({ error: "Benutzername oder Passwort ist falsch." }, 401);
  }

  if (user.status === "pending") {
    return json({ error: "Dein Konto wartet noch auf Freischaltung durch einen Admin." }, 403);
  }
  if (user.status === "rejected") {
    return json({ error: "Dein Konto wurde nicht freigeschaltet." }, 403);
  }

  const token = randomToken();
  await env.DB.prepare(
    "INSERT INTO sessions (token, user_id, expires_at) VALUES (?1, ?2, datetime('now', '+7 days'))"
  )
    .bind(token, user.id)
    .run();

  return new Response(JSON.stringify({ ok: true }), {
    status: 200,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Set-Cookie": sessionCookie(token),
    },
  });
}

async function handleLogout(request, env) {
  const cookies = parseCookies(request);
  const token = cookies["session"];
  if (token) {
    await env.DB.prepare("DELETE FROM sessions WHERE token = ?1").bind(token).run();
  }
  return new Response(JSON.stringify({ ok: true }), {
    status: 200,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Set-Cookie": clearSessionCookie(),
    },
  });
}

async function adminListPending(env) {
  const { results } = await env.DB.prepare(
    "SELECT id, username, vorname, nachname, email, handynummer, created_at FROM users WHERE status = 'pending' ORDER BY created_at ASC"
  ).all();
  return { users: results };
}

async function adminListAll(env) {
  const { results } = await env.DB.prepare(
    "SELECT id, username, vorname, nachname, email, handynummer, role, status, created_at FROM users ORDER BY created_at DESC"
  ).all();
  return { users: results };
}

async function adminSetStatus(env, request, status) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungültige Anfrage." }, 400);
  }
  const userId = Number(body.userId);
  if (!userId) return json({ error: "userId fehlt." }, 400);
  await env.DB.prepare("UPDATE users SET status = ?1, updated_at = datetime('now') WHERE id = ?2")
    .bind(status, userId)
    .run();
  await notifyAdmins(env);
  return json({ ok: true });
}

async function adminPromote(env, request) {
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Ungültige Anfrage." }, 400);
  }
  const userId = Number(body.userId);
  if (!userId) return json({ error: "userId fehlt." }, 400);
  await env.DB.prepare("UPDATE users SET role = 'admin', updated_at = datetime('now') WHERE id = ?1")
    .bind(userId)
    .run();
  await notifyAdmins(env);
  return json({ ok: true });
}

async function notifyAdmins(env) {
  try {
    const id = env.TODO_ROOM.idFromName("admin-room");
    const stub = env.TODO_ROOM.get(id);
    await stub.notify({ type: "users:changed" });
  } catch {
    // Admin-Panel evtl. gerade nicht offen -- kein Problem.
  }
}

// =====================================================================
// ROUTER
// =====================================================================
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    // ---- Öffentliche Auth-Routen ----
    if (path === "/auth/register" && request.method === "POST") return handleRegister(request, env);
    if (path === "/auth/login" && request.method === "POST") return handleLogin(request, env);
    if (path === "/auth/logout" && request.method === "POST") return handleLogout(request, env);
    if (path === "/login.html" || path === "/login") return htmlResponse(LOGIN_HTML);
    if (path === "/login.js") return jsResponse(LOGIN_JS);

    const user = await getSessionUser(request, env);

    // ---- Admin-Bereich ----
    if (path.startsWith("/admin")) {
      if (!user) return Response.redirect(url.origin + "/login.html", 302);
      if (user.role !== "admin" || user.status !== "approved") {
        return new Response("Forbidden", { status: 403 });
      }
      if (path === "/admin" || path === "/admin/") return htmlResponse(ADMIN_HTML);
      if (path === "/admin.js") return jsResponse(ADMIN_JS);
      if (path === "/admin/ws") {
        const upgradeHeader = request.headers.get("Upgrade");
        if (!upgradeHeader || upgradeHeader !== "websocket") {
          return new Response("Erwarte Upgrade: websocket", { status: 426 });
        }
        const adminRoomId = env.TODO_ROOM.idFromName("admin-room");
        const adminStub = env.TODO_ROOM.get(adminRoomId);
        return adminStub.fetch(request);
      }
      if (path === "/admin/api/pending" && request.method === "GET") return json(await adminListPending(env));
      if (path === "/admin/api/users" && request.method === "GET") return json(await adminListAll(env));
      if (path === "/admin/api/approve" && request.method === "POST") return adminSetStatus(env, request, "approved");
      if (path === "/admin/api/reject" && request.method === "POST") return adminSetStatus(env, request, "rejected");
      if (path === "/admin/api/promote" && request.method === "POST") return adminPromote(env, request);
      return new Response("Not found", { status: 404 });
    }

    // ---- Geschützte App-Routen ----
    if (!user || user.status !== "approved") {
      if (path === "/ws") return new Response("Unauthorized", { status: 401 });
      return Response.redirect(url.origin + "/login.html", 302);
    }

    if (path === "/ws") {
      const upgradeHeader = request.headers.get("Upgrade");
      if (!upgradeHeader || upgradeHeader !== "websocket") {
        return new Response("Erwarte Upgrade: websocket", { status: 426 });
      }
      const id = env.TODO_ROOM.idFromName("main-room");
      const stub = env.TODO_ROOM.get(id);
      return stub.fetch(request);
    }

    if (path === "/" || path === "/index.html") {
      const displayName = user.vorname + " " + user.nachname;
      return htmlResponse(buildAppHtml(displayName, user.role === "admin"));
    }

    return new Response("Not found", { status: 404 });
  },
};


// ---- Durable Object: hält die Aufgabenliste & alle WebSocket-Verbindungen ----
export class TodoRoom extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.tasks = [];

    // Beim (Re-)Start der DO gespeicherte Aufgaben laden, bevor Requests bedient werden.
    ctx.blockConcurrencyWhile(async () => {
      this.tasks = (await this.ctx.storage.get("tasks")) || [];
    });
  }

  async fetch(request) {
    const webSocketPair = new WebSocketPair();
    const [client, server] = Object.values(webSocketPair);

    // Hibernatable WebSocket: die DO kann bei Inaktivität aus dem Speicher entfernt
    // werden, ohne dass die Verbindung getrennt wird.
    this.ctx.acceptWebSocket(server);

    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws, raw) {
    let msg;
    try {
      msg = JSON.parse(raw);
    } catch {
      return;
    }

    switch (msg.type) {
      case "hello": {
        // Neu verbundener Client bekommt den aktuellen Stand.
        ws.send(JSON.stringify({ type: "init", tasks: this.tasks }));
        break;
      }

      case "task:create": {
        if (!msg.title || !msg.title.trim()) return;
        const task = {
          id: crypto.randomUUID(),
          title: msg.title.trim(),
          note: msg.note || "",
          subtasks: [],
          createdBy: msg.user || "Unbekannt",
          createdAt: new Date().toISOString(),
        };
        this.tasks.push(task);
        await this.save();
        this.broadcast({ type: "task:created", task });
        break;
      }

      case "task:delete": {
        const idx = this.tasks.findIndex((t) => t.id === msg.taskId);
        if (idx === -1) return;
        this.tasks.splice(idx, 1);
        await this.save();
        this.broadcast({ type: "task:deleted", taskId: msg.taskId });
        break;
      }

      case "task:update": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;
        if (typeof msg.title === "string") task.title = msg.title;
        if (typeof msg.note === "string") task.note = msg.note;
        await this.save();
        this.broadcast({ type: "task:updated", task });
        break;
      }

      case "subtask:create": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task || !msg.title || !msg.title.trim()) return;
        const subtask = {
          id: crypto.randomUUID(),
          title: msg.title.trim(),
          done: false,
          doneBy: null,
          doneAt: null,
        };
        task.subtasks.push(subtask);
        await this.save();
        this.broadcast({ type: "subtask:created", taskId: msg.taskId, subtask });
        break;
      }

      case "subtask:toggle": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;
        const sub = task.subtasks.find((s) => s.id === msg.subtaskId);
        if (!sub) return;
        sub.done = !sub.done;
        sub.doneBy = sub.done ? msg.user || "Unbekannt" : null;
        sub.doneAt = sub.done ? new Date().toISOString() : null;
        await this.save();
        this.broadcast({ type: "subtask:updated", taskId: msg.taskId, subtask: sub });
        break;
      }

      case "subtask:delete": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;
        task.subtasks = task.subtasks.filter((s) => s.id !== msg.subtaskId);
        await this.save();
        this.broadcast({ type: "subtask:deleted", taskId: msg.taskId, subtaskId: msg.subtaskId });
        break;
      }

      case "subtask:update": {
        const task = this.tasks.find((t) => t.id === msg.taskId);
        if (!task) return;
        const sub = task.subtasks.find((s) => s.id === msg.subtaskId);
        if (!sub) return;
        if (typeof msg.title === "string") sub.title = msg.title;
        await this.save();
        this.broadcast({ type: "subtask:updated", taskId: msg.taskId, subtask: sub });
        break;
      }
    }
  }

  async webSocketClose(ws, code, reason, wasClean) {
    ws.close(code, reason);
  }

  async webSocketError(ws) {
    // Verbindung war fehlerhaft; nichts weiter zu tun, die Runtime räumt sie auf.
  }

  broadcast(msg) {
    const payload = JSON.stringify(msg);
    for (const ws of this.ctx.getWebSockets()) {
      try {
        ws.send(payload);
      } catch {
        // tote Verbindung ignorieren
      }
    }
  }

  // RPC-Methode: wird direkt vom Worker aufgerufen (kein WebSocket noetig),
  // um verbundene Clients (z.B. das Admin-Panel) sofort zu benachrichtigen.
  notify(msg) {
    this.broadcast(msg);
  }

  async save() {
    await this.ctx.storage.put("tasks", this.tasks);
  }
}
